using System;\nusing TechTalk.SpecFlow;\nusing RestSharp;\nusing Serilog;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreCRUDSteps\n    {\n        private readonly RestClient _client;\n        private RestResponse _response;\n        private string _petId;\n\n        public PetstoreCRUDSteps()\n        {\n            _client = new RestClient(\"https://petstore.swagger.io/v2/pet\");\n        }\n\n        [Given(\"I have a valid pet payload\")]  \n        public void GivenIHaveAValidPetPayload()\n        {\n            var petPayload = new\n            {\n                id = 1,\n                name = \"Dog\",\n                status = \"available\"\n            };\n            var request = new RestRequest(Method.POST);\n            request.AddJsonBody(petPayload);\n            _response = _client.Execute(request);\n            Log.Information(\"POST request sent with payload: {Payload}\", petPayload);\n        }\n\n        [When(\"I send a POST request to the petstore API\")]  \n        public void WhenISendAPostRequestToThePetstoreAPI()\n        {\n            // This step is already handled in the previous step\n        }\n\n        [Then(\"the response status code should be 200\")]  \n        public void ThenTheResponseStatusCodeShouldBe200()\n        {\n            if (_response.StatusCode != System.Net.HttpStatusCode.OK)\n            {\n                throw new Exception(\"Expected status code 200 but got \" + _response.StatusCode);\n            }\n            Log.Information(\"Response status code: {StatusCode}\", _response.StatusCode);\n        }\n\n        [Given(\"a pet with ID 1 exists\")]  \n        public void GivenAPetWithID1Exists()\n        {\n            _petId = \"1\";\n        }\n\n        [When(\"I send a GET request to the petstore API for that pet\")]  \n        public void WhenISendAGetRequestToThePetstoreAPIForThatPet()\n        {\n            var request = new RestRequest($\"/{_petId}\", Method.GET);\n            _response = _client.Execute(request);\n            Log.Information(\"GET request sent for pet ID: {PetId}\", _petId);\n        }\n\n        [When(\"I send a PUT request to update the pet\")]  \n        public void WhenISendAPutRequestToUpdateThePet()\n        {\n            var petPayload = new\n            {\n                id = 1,\n                name = \"Dog Updated\",\n                status = \"available\"\n            };\n            var request = new RestRequest($\"/{_petId}\", Method.PUT);\n            request.AddJsonBody(petPayload);\n            _response = _client.Execute(request);\n            Log.Information(\"PUT request sent to update pet ID: {PetId} with payload: {Payload}\", _petId, petPayload);\n        }\n\n        [When(\"I send a DELETE request to the petstore API for that pet\")]  \n        public void WhenISendADeleteRequestToThePetstoreAPIForThatPet()\n        {\n